+  addi(a1, a1, bytes_m4);
+  addi(a2, a2, bytes_m4);
+  bge(cnt, tmp1, loop);
+  beqz(cnt, same);
+
+  // Tail: one vl-bounded compare covers the rest.
+  vsetvli(tmp1, cnt, sew, Assembler::m4, Assembler::ma, Assembler::ta);
+  vlex_v(va, a1, sew);
+  vlex_v(vb, a2, sew);
+  vmsne_vv(va, va, vb);
+  vfirst_m(tmp2, va);
+  bgez(tmp2, DONE);
